                                "ERROR: sdp_mangle_port: Received <= 0 for Content-Length \n");
                return -2;
        }

        if(offset == NULL)
                return -14;
        if(sscanf(offset, "%d", &offsetValue) != 1) {
                LOG(L_ERR, "ERROR: sdp_mangle_port: Invalid value for offset \n");
                return -13;
