        /* try to use pre-compiled expressions */
        needToDealocate = 0;
        if(portExpression != NULL) {
                re = portExpression;
#ifdef EXTRA_DEBUG
                fprintf(stdout, "Using PRECOMPILED expression for port ...\n");
#endif
