                if(re == NULL) {
                        LOG(L_ERR, "ERROR: sdp_mangle_port: Unable to allocate re\n");
                        return -4;
                }
                needToDealocate = 1;
                if((regcomp(re, key, REG_EXTENDED)) != 0) {
                        LOG(L_ERR, "ERROR: sdp_mangle_port: Unable to compile %s \n", key);
