                pos = (char *) memrchr (begin + pmatch.rm_so, ' ',pmatch.rm_eo - pmatch.rm_so);
                */
                pos = begin + pmatch.rm_eo;
#ifdef EXTRA_DEBUG
                printf("begin=%c pos=%c rm_so=%d rm_eo=%d\n", *begin, *pos,
                                pmatch.rm_so, pmatch.rm_eo);
#endif
